<h1>Counter Management</h1><?php if(isset($_GET['saved'])):?><p class="ok">Counter settings saved.</p><?php endif?><div class="grid2"><section class="card"><h2 id="counter-form-title">Add counter</h2><form method="post" id="counter-form"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" id="counter-id"><label>Counter name<input name="name" id="counter-name" placeholder="Loket PTK" required></label><label>Code<input name="code" id="counter-code" maxlength="20" placeholder="PTK" required></label><fieldset><legend>Assigned services</legend><div class="check-grid"><?php foreach($services as $service):?><label><input type="checkbox" name="service_ids[]" value="<?=e($service['id'])?>"> <?=e($service['name'])?></label><?php endforeach?></div></fieldset><label class="media-check"><input type="checkbox" name="active" id="counter-active" checked> Active</label><button type="submit">Save counter</button><button type="button" class="secondary" id="counter-reset">New counter</button></form></section><section><table><thead><tr><th>Code</th><th>Counter</th><th>Services</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($counters as $counter):?><tr><td><?=e($counter['code'])?></td><td><?=e($counter['name'])?></td><td><?=e($counter['service_names']??'-')?></td><td><?=$counter['active']?'Active':'Inactive'?></td><td><button type="button" class="edit-counter secondary" data-counter='<?=e(json_encode(['id'=>$counter['id'],'name'=>$counter['name'],'code'=>$counter['code'],'active'=>(bool)$counter['active'],'services'=>array_map('intval',explode(',',$counter['service_ids']??''))],JSON_UNESCAPED_UNICODE))?>'>Edit</button></td></tr><?php endforeach?></tbody></table></section></div><script src="/assets/counters.js"></script>
